define(["jquery"],(function(t){"use strict";return{init:function(e){t(document).on("click",".show-more-btn",(function(a){a.preventDefault();var s=t(this),n=String(s.data("full-text")),r=s.prev("pre");s.hasClass("expanded")?(r.text(n.substring(0,500)+"..."),s.text(e.showMore),s.removeClass("expanded")):(r.text(n),s.text(e.showLess),s.addClass("expanded"))})),t(document).on("click",".ai-log-expand",(function(){var a=t(this),s=t(a.attr("data-bs-target"));s.toggleClass("show"),s.hasClass("show")?(a.text(e.collapsePrompts),a.attr("aria-expanded","true")):(a.text(e.expandPrompts),a.attr("aria-expanded","false"))}))}}}));